using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.ImageSource;
static class Program {
 static int checks;
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
 sealed class Transport:IAcquisitionLightModuleTransport {public int Return;public List<(int Module,string Command,byte[] Data)> Writes=[];public IReadOnlyList<AcquisitionLightDevice> Devices{get;set;}=[];public ValueTask SetBinaryDataAsync(int module,string command,ReadOnlyMemory<byte> data,CancellationToken token){token.ThrowIfCancellationRequested();Writes.Add((module,command,data.ToArray()));if(Return!=0)throw new IOException("Controlled transport failure");return ValueTask.CompletedTask;}}
 static Dictionary<string,JsonElement> Defaults(LightPlugin plugin)=>plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());
 static void Set<T>(Dictionary<string,JsonElement> p,string key,T value)=>p[key]=JsonSerializer.SerializeToElement(value);
 [STAThread]static int Main(){try{Replay().GetAwaiter().GetResult();Integration().GetAwaiter().GetResult();Ui();Console.WriteLine($"Light.PluginChecks: {checks} passed");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static async Task Replay(){using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/light-evidence.json"));var plugin=new LightPlugin();using var scope=new ModuleExecutionScope();var transport=new Transport();scope.RegisterService<IAcquisitionLightModuleTransport>(transport);
  foreach(var row in evidence.RootElement.GetProperty("rows").EnumerateArray().Where(r=>r.TryGetProperty("values",out _))){string phase=row.GetProperty("phase").GetString()!;string node=phase.StartsWith("type-")?string.Join('-',phase.Split('-').Take(2)):"unbound";var p=Defaults(plugin);foreach(var pair in row.GetProperty("parameters").EnumerateObject()){var spec=plugin.Descriptor.Parameters.FirstOrDefault(s=>s.Name==pair.Name);if(spec is null)continue;string text=pair.Value.GetString()!;p[pair.Name]=spec.Kind switch{ParameterKind.Boolean=>JsonSerializer.SerializeToElement(text=="True"),ParameterKind.Integer=>JsonSerializer.SerializeToElement(int.Parse(text,System.Globalization.CultureInfo.InvariantCulture)),_=>JsonSerializer.SerializeToElement(text)};}
   var input=new Dictionary<string,PortValue>();foreach(var pair in row.GetProperty("inputs").EnumerateObject())input[pair.Name]=pair.Value.ValueKind==JsonValueKind.String?PortValue.Text(pair.Value.GetString()!):PortValue.Integer(pair.Value.GetInt32());transport.Return=row.GetProperty("transportReturn").GetInt32();transport.Writes.Clear();var result=await plugin.CreateRuntime().ExecuteAsync(new(node,Environment.CurrentDirectory,input,p){Scope=scope},default);Check(result.NativeErrorCode==row.GetProperty("code").GetUInt32(),phase+" native error");var expected=row.GetProperty("values");Check(result.Outputs.Count-1==expected.EnumerateObject().Count(),phase+" output presence");foreach(var field in expected.EnumerateObject()){Check(field.Value.GetArrayLength()==1,phase+" scalar shape");Check(result.Outputs.TryGetValue(field.Name,out var value)&&value.As<long>()==field.Value[0].GetInt32(),phase+" "+field.Name);}var writes=row.GetProperty("writes").EnumerateArray().ToArray();Check(transport.Writes.Count==writes.Length,phase+" exact send count");for(int i=0;i<writes.Length;i++){var expectedWrite=writes[i];var actual=transport.Writes[i];Check(actual.Module==expectedWrite.GetProperty("module").GetInt32()&&actual.Command==expectedWrite.GetProperty("command").GetString(),phase+" routing");Check(Convert.ToHexString(actual.Data).ToLowerInvariant()==expectedWrite.GetProperty("hex").GetString(),phase+" all 748 command bytes");}
  }
  foreach(var row in evidence.RootElement.GetProperty("rows").EnumerateArray().Where(r=>r.GetProperty("phase").GetString()=="sdk-ui")){int type=row.GetProperty("deviceType").GetInt32();var fields=LightUiRules.Fields(type).ToDictionary(f=>f.Name);foreach(var item in row.GetProperty("items").EnumerateArray()){var p=item.GetProperty("properties");string name=p.GetProperty("NameA").GetString()!;if(!fields.TryGetValue(name,out var field))continue;Check(field.Visible==(p.GetProperty("CustomVisibleA").GetString()=="True"),$"native UI visibility {type} {name}");if(field.Visible&&field.Kind=="Integer")Check(field.Minimum==int.Parse(p.GetProperty("MinValueA").GetString()!)&&field.Maximum==int.Parse(p.GetProperty("MaxValueA").GetString()!),$"native UI range {type} {name}");}}
 }
 static async Task Integration(){var plugin=new LightPlugin();var registry=new ModuleRegistry();new ToolPluginRegistry().Register(plugin,registry);var p=Defaults(plugin);Set(p,"LightDevice","0#42#101#fixture");Set(p,"Channel1Enable",true);Set(p,"Channel1Brightness",45);var node=new NodeDocument("light",LightPlugin.Id,"1.0.0","光源",p);var flow=new ProcedureDocument("flow","流程",[node],[],[]){Configuration=new(){Subscriptions=[new("light","InputString",false,new(WorkflowSourceKind.TextConstant,JsonSerializer.Serialize("OK")))]}};Check(LightPlugin.Device.Parse(LightPlugin.DeviceSelection(new(1,"old",14000,0,25690628,"id"))).Type==105,"old global catalog hardware type mapping");Check(LightPlugin.Device.Parse(LightPlugin.DeviceSelection(new(1,"modern",77,0,25690628,"id"))).Type==25690628,"modern catalog does not apply old-global mapping");Check(LightPlugin.Device.Parse("0#1#101#a#b").Guid=="a#b","identifier retains separator suffix");Check(GraphValidator.Validate(flow,registry).IsValid,"text constant validation");using var scope=new ModuleExecutionScope();var transport=new Transport();scope.RegisterService<IAcquisitionLightModuleTransport>(transport);var graph=new GraphExecutor(registry);var run=await graph.RunAsync(flow,Environment.CurrentDirectory,scope:scope);Check(run.Status==SessionStatus.Success&&run.Nodes.Single().Status==NodeRunStatus.Success,"graph execution succeeds");Check(transport.Writes.Count==1,"graph uses text constant");string path=Path.GetFullPath("analysis/full-audit/light/roundtrip.vmx.json");SolutionStore.Save(path,new(1,"test","光源验证",[flow],[]));var loaded=SolutionStore.Load(path);Check(loaded.Procedures.Single().Configuration.Subscriptions.Single().Source.Kind==WorkflowSourceKind.TextConstant,"text constant persistence");transport.Return=-1;var failedSend=await graph.RunAsync(flow,Environment.CurrentDirectory,scope:scope);Check(failedSend.Nodes.Single().Status==NodeRunStatus.NoMatch&&failedSend.Nodes.Single().NativeErrorCode==0,"transport failure is native NG without error code");
  var noTrigger=flow with{Configuration=new()};transport.Writes.Clear();var held=await graph.RunAsync(noTrigger,Environment.CurrentDirectory,scope:scope);Check(held.Nodes.Single().Outputs["Channel1Brightness"].As<long>()==45&&transport.Writes.Count==0,"no trigger retains effective brightness");scope.RemoveNode(LightPlugin.Id,"light");Check((await graph.RunAsync(noTrigger,Environment.CurrentDirectory,scope:scope)).Nodes.Single().Outputs["Channel1Brightness"].As<long>()==0,"node removal resets effective state");
  foreach(string literal in new[]{"null","1","{bad}"}){var bad=flow with{Configuration=new(){Subscriptions=[new("light","InputString",false,new(WorkflowSourceKind.TextConstant,literal))]}};Check(!GraphValidator.Validate(bad,registry).IsValid,"malformed text constant rejected");}foreach(string text in new[]{""," ","OK\0tail","中文"}){var encoded=JsonSerializer.Serialize(text);Check(WorkflowSubscriptions.ReadTextConstant(encoded)==text,"text literal lossless");}var wrong=flow with{Configuration=new(){Subscriptions=[new("light","InputChannel1Brightness",false,new(WorkflowSourceKind.TextConstant,"\"1\""))]}};Check(!GraphValidator.Validate(wrong,registry).IsValid,"text cannot bind integer");using var stop=new CancellationTokenSource();stop.Cancel();try{await plugin.CreateRuntime().ExecuteAsync(new("stop",Environment.CurrentDirectory,new Dictionary<string,PortValue>(),p){Scope=scope},stop.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){checks++;}
 }
 static IEnumerable<DependencyObject> Children(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);yield return child;foreach(var next in Children(child))yield return next;}}
 static void Ui(){SynchronizationContext.SetSynchronizationContext(new System.Windows.Threading.DispatcherSynchronizationContext(System.Windows.Threading.Dispatcher.CurrentDispatcher));foreach(int type in new[]{0,101,102,103,104,105,107,109,110,113,114,8917764})foreach(int mode in new[]{1,2}){var plugin=new LightPlugin();var p=Defaults(plugin);using(var original=JsonDocument.Parse(File.ReadAllText("docs/plugins/light-evidence.json"))){var record=original.RootElement.GetProperty("rows").EnumerateArray().First(r=>r.GetProperty("phase").GetString()==(type==0?"unbound-default":$"type-{type}-recover"));foreach(var pair in record.GetProperty("parameters").EnumerateObject()){var spec=plugin.Descriptor.Parameters.FirstOrDefault(d=>d.Name==pair.Name);if(spec is null)continue;string value=pair.Value.GetString()!;p[pair.Name]=spec.Kind switch{ParameterKind.Boolean=>JsonSerializer.SerializeToElement(value=="True"),ParameterKind.Integer=>JsonSerializer.SerializeToElement(int.Parse(value)),_=>JsonSerializer.SerializeToElement(value)};}}Set(p,"InputType",mode);var node=new NodeDocument("ui",LightPlugin.Id,"1.0.0","光源",p);int runs=0,applies=0;Dictionary<string,JsonElement>? latest=null;var cleared=new List<string>();var calls=new List<string>();var texts=new Dictionary<string,string>();using var scope=new ModuleExecutionScope();var transport=new Transport{Devices=[new(1,"测试资源",42,0,type,"fixture")]};scope.RegisterService<IAcquisitionLightModuleTransport>(transport);var window=plugin.CreateWpfEditor(new(node,Environment.CurrentDirectory,values=>{applies++;latest=values;},_=>{runs++;return Task.FromResult(new NodeRunRecord("ui",NodeRunStatus.Success,new Dictionary<string,PortValue>(),0));}){Scope=scope,Mode=ToolEditorMode.SdkEmbedded,SetInputInteger=(key,value)=>{if(value is null)cleared.Add(key);},SetInputText=(key,value)=>{if(value is null)texts.Remove(key);else texts[key]=value;},SubscriptionLabel=(key,parameter)=>texts.GetValueOrDefault(key),PickSubscription=(owner,key,parameter,kind)=>{calls.Add(key);return "绑定";},ConfigureLights=()=>calls.Add("resources")});window.Left=-30000;window.Top=-30000;window.Height=1200;window.ShowActivated=false;window.ShowInTaskbar=false;window.Show();window.UpdateLayout();var elements=Children(window).OfType<FrameworkElement>().ToArray();var fields=LightUiRules.Fields(type);foreach(var field in fields.Where(f=>f.Name.StartsWith("Channel")))Check(elements.Any(e=>e.Name==field.Name)==field.Visible,"dedicated UI field "+type+" "+field.Name);Check(elements.OfType<TextBlock>().Any(t=>t.Text=="光源设备")&&elements.OfType<TextBlock>().Any(t=>t.Text=="通道参数"),"original category labels");window.UpdateLayout();var bitmap=new RenderTargetBitmap(420,1200,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));Directory.CreateDirectory("analysis/full-audit/light");using(var output=File.Create($"analysis/full-audit/light/independent-{type}-{mode}.png"))encoder.Save(output);var text=elements.OfType<System.Windows.Controls.TextBox>().Single(t=>t.Name=="InputInputString");text.Text="OK";text.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,PresentationSource.FromVisual(window)!,Environment.TickCount,System.Windows.Input.Key.Enter){RoutedEvent=System.Windows.Input.Keyboard.KeyDownEvent});Check(texts["InputString"]=="OK","trigger literal edit");var buttons=elements.OfType<System.Windows.Controls.Button>().ToArray();buttons.Single(b=>b.Name=="SubscribeInputString").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(calls.Contains("InputString"),"trigger subscription callback");buttons.Single(b=>b.Name=="ConfigureLightResources").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(calls.Contains("resources"),"resource-manager callback");buttons=Children(window).OfType<System.Windows.Controls.Button>().ToArray();buttons.Single(b=>b.Name=="ExecuteLight").RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));Check(runs==1,"execute callback");if(type==101&&mode==1){var picker=Children(window).OfType<System.Windows.Controls.ComboBox>().Single(c=>c.Name=="LightDevicePicker");picker.SelectedIndex=1;Check(latest is not null&&Enumerable.Range(1,8).All(i=>!latest[$"Channel{i}Enable"].GetBoolean()&&latest[$"Channel{i}DurationTime"].GetInt32()==0),"device selection resets staged channel settings");Check(latest!["Channel1Brightness"].GetInt32()==50,"device selection retains manual brightness cache");Check(cleared.SequenceEqual(Enumerable.Range(1,6).Select(i=>$"InputChannel{i}Brightness")),"device change clears first six brightness subscriptions");}window.Close();}}
}
